import{St as e,at as t,it as n,n as r,st as i,vt as a}from"./chunks/framework.yntlMcNk.js";var o=JSON.parse(`{"title":"Catalogs","description":"","frontmatter":{"title":"Catalogs","covers":{"screens":["SCR-020","SCR-028"],"stories":["US-046","US-047","US-049"]}},"headers":[],"relativePath":"usage/catalogs.md","filePath":"usage/catalogs.md"}`),s={name:`usage/catalogs.md`};function c(r,o,s,c,l,u){let d=e(`Screenshot`);return a(),n(`div`,null,[o[0]||=t(`<h1 id="catalogs" tabindex="-1">Catalogs <a class="header-anchor" href="#catalogs" aria-label="Permalink to “Catalogs”">​</a></h1><p>A catalog is a reusable table view of the repository. It shows the entities of one entity type as rows. You need the permission <code>entity:read</code> (for example the role <code>viewer</code>) to see catalogs and create personal ones; shared catalogs need <code>catalog:manage</code> (role <code>enterprise-architect</code>).</p><h2 id="create-a-catalog" tabindex="-1">Create a catalog <a class="header-anchor" href="#create-a-catalog" aria-label="Permalink to “Create a catalog”">​</a></h2><ol><li><p>Choose <em>Catalogs</em> in the header, then <em>New catalog</em>.</p></li><li><p>Fill in the dialog <em>New catalog</em>:</p><table tabindex="0"><thead><tr><th>Field</th><th>Meaning</th></tr></thead><tbody><tr><td>Name</td><td>required; unique within the instance, regardless of upper and lower case</td></tr><tr><td>Description</td><td>optional, up to 1000 characters</td></tr><tr><td>Primary entity type</td><td>required; its entities become the rows of the table</td></tr><tr><td>Visibility</td><td><em>Shared</em>: visible to all users of the instance (needs the permission to manage catalogs); <em>Personal</em>: visible only to you</td></tr><tr><td>Default join mode</td><td><em>Aggregate</em>: one row per entity, linked entities in one cell; <em>Rows</em>: one row per linked entity. Applies to joins added later</td></tr></tbody></table></li></ol>`,4),i(d,{name:`catalog-create`,alt:`Dialog New catalog with name, description, entity type and visibility`}),o[1]||=t(`<ol start="3"><li>Choose <em>Create catalog</em>. The new catalog opens.</li></ol><p>If the name is already taken, the dialog says so; choose another name. Without the permission to manage catalogs, <em>Shared</em> is not selectable.</p><h2 id="browse-a-catalog" tabindex="-1">Browse a catalog <a class="header-anchor" href="#browse-a-catalog" aria-label="Permalink to “Browse a catalog”">​</a></h2><p>The list <em>Catalogs</em> shows every catalog you may see, marked <em>Shared</em> or <em>Personal</em>. Open one to see its table:</p>`,4),i(d,{name:`catalogs`,alt:`List of catalogs`}),i(d,{name:`catalog-table`,alt:`Table of a catalog with application components`}),o[2]||=t(`<ul><li>Names of entity types, column headers and values of enum properties appear in your language where your organization has translated them (see <a href="./login#your-profile">Your profile</a>).</li><li>As long as no columns are configured (see <a href="#configure-columns">Configure columns</a>), the table shows the columns <em>Name</em> and – if the entity type has the property <em>Status</em> – <em>Status</em>.</li><li>Values of an enum property, such as <em>Status</em>, are sorted in the order of the values, not alphabetically; entries without a value come last.</li><li>Click a column header to sort: ascending, descending, and back to the default order.</li><li>The table shows 50 entries per page; use the pagination below the table to move between pages.</li><li>Sort and page are part of the address of the page. Back navigation, a reload or a shared link restore the same view; invalid values in the address are ignored and the first page is shown in the default order.</li><li>If the entity type has no entities yet, the table shows <em>No entries found</em>.</li><li>Another person&#39;s personal catalog cannot be opened; it behaves like a catalog that does not exist (<em>Catalog not found</em>).</li></ul><p>Through the API, <code>GET /catalogs/{id}/query</code> returns the same rows with the parameters <code>page</code> (from 0), <code>pageSize</code> (1–200, default 50) and <code>sort</code> (<code>{field}:{asc|desc}</code>).</p><h2 id="configure-columns" tabindex="-1">Configure columns <a class="header-anchor" href="#configure-columns" aria-label="Permalink to “Configure columns”">​</a></h2><p>You decide which attributes a catalog shows, in which order and under which header. A shared catalog needs the permission to manage catalogs (<code>catalog:manage</code>, role <code>enterprise-architect</code>); your own personal catalog you configure yourself.</p><ol><li>Open the catalog and choose <em>Configure columns</em>.</li><li>The dialog lists every attribute of the entity type: the fields <em>Name</em>, <em>Description</em>, <em>External ID</em>, <em>Created</em>, <em>Updated</em> and <em>Version</em>, and every property assigned to the entity type, also the inherited ones.</li><li>Per row: <ul><li><em>Visible</em> shows or hides the column. A hidden column stays in the list, so you can show it again later.</li><li><em>Header</em> replaces the name of the attribute in the table, for example <em>Operational Status</em> for <em>Status</em>.</li><li><em>Sortable</em> decides whether readers may sort by the column.</li></ul></li><li>Change the order by dragging a row, or with the arrow buttons of a row.</li><li>Under <em>Default sort</em>, choose the column and direction the table is sorted by when nobody chose a sort.</li><li>Choose <em>Save</em>. At least one column must be visible.</li></ol><p>A property that is no longer assigned to the entity type shows as <em>Not available</em> and is removed when you save. Every change is recorded in the audit trail.</p><p>Through the API, <code>PUT /catalogs/{id}/columns</code> replaces the list. Each column names a field (<code>&quot;field&quot;: &quot;name&quot;</code>, <code>description</code>, <code>externalId</code>, <code>createdAt</code>, <code>updatedAt</code>, <code>entityVersion</code>) or a property (<code>&quot;propertyDefId&quot;: &quot;…&quot;</code>), with <code>displayLabel</code>, <code>visible</code>, <code>sortable</code> and at most one <code>defaultSortDirection</code> (<code>asc</code> or <code>desc</code>). An empty list restores the default columns.</p>`,7)])}var l=r(s,[[`render`,c]]);export{o as __pageData,l as default};